def hanoi_sequence(n):
    moves = []
    def go(k, src, dst, via):
        if k == 0:
            return
        go(k - 1, src, via, dst)
        moves.append([src, dst])
        go(k - 1, via, dst, src)
    go(n, 'A', 'C', 'B')
    return moves
